import Foundation
final class ToolLedger {
    private let lock = NSLock()
    private var available = 2
    private var borrowed = 0
    func take() -> Bool {
        lock.lock(); defer { lock.unlock() }
        guard available > 0 else { return false }
        available -= 1
        borrowed += 1
        return true
    }
    func snapshot() -> (available: Int, borrowed: Int) {
        lock.lock(); defer { lock.unlock() }
        return (available, borrowed)
    }
}

После двух take true, true, третий false. snapshot (0, 2), сумма остаётся 2. Это синхронный снимок, не обещание заморозить состояние на время будущего await. Выбор здесь — NSLock для короткого синхронного API; serial queue.sync тоже сохраняет синхронность, actor требует await из другого контекста.

